"""JSON-backed registry of named connector configurations."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from agentic_odi_connectors.models import ConnectorConfig


class UnknownConnectorKindError(ValueError):
    def __init__(self, kind: str) -> None:
        self.kind = kind
        super().__init__(f"Unknown connector kind: {kind}")


class DuplicateConnectorError(ValueError):
    def __init__(self, name: str) -> None:
        self.name = name
        super().__init__(f"Connector already exists: {name}")


class ConnectorNotFoundError(ValueError):
    def __init__(self, name: str) -> None:
        self.name = name
        super().__init__(f"Connector not found: {name}")


def _known_kinds() -> set[str]:
    from agentic_odi_connectors.factory import known_kinds

    return known_kinds()


class ConnectorRegistry:
    """Persists connector configs to a JSON file."""

    def __init__(self, path: Path) -> None:
        self.path = path

    def add(self, config: ConnectorConfig) -> None:
        if config.kind not in _known_kinds():
            raise UnknownConnectorKindError(config.kind)
        connectors = self._load()
        if any(existing.name == config.name for existing in connectors):
            raise DuplicateConnectorError(config.name)
        connectors.append(config)
        self._save(connectors)

    def list_all(self) -> list[ConnectorConfig]:
        return self._load()

    def get(self, name: str) -> ConnectorConfig:
        for config in self._load():
            if config.name == name:
                return config
        raise ConnectorNotFoundError(name)

    def delete(self, name: str) -> bool:
        connectors = self._load()
        kept = [config for config in connectors if config.name != name]
        if len(kept) == len(connectors):
            raise ConnectorNotFoundError(name)
        self._save(kept)
        return True

    def _load(self) -> list[ConnectorConfig]:
        if not self.path.exists():
            return []
        with self.path.open(encoding="utf-8") as handle:
            payload: dict[str, Any] = json.load(handle)
        raw_connectors = payload.get("connectors", [])
        return [ConnectorConfig.model_validate(item) for item in raw_connectors]

    def _save(self, connectors: list[ConnectorConfig]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = {"connectors": [item.model_dump(mode="json") for item in connectors]}
        with self.path.open("w", encoding="utf-8") as handle:
            json.dump(payload, handle, indent=2)
            handle.write("\n")

"""Kind registry that maps connector configs onto Connector implementations."""

from __future__ import annotations

from collections.abc import Callable

from agentic_odi_connectors.mcp.connector import MCPClientConnector
from agentic_odi_connectors.models import (
    ConnectorConfig,
    McpConnectorSettings,
    RestConnectorSettings,
)
from agentic_odi_connectors.protocol import Connector
from agentic_odi_connectors.registry import UnknownConnectorKindError
from agentic_odi_connectors.rest.connector import RestConnector, WebhookConnector

Builder = Callable[[ConnectorConfig], Connector]

_builders: dict[str, Builder] = {}


def register_kind(kind: str, builder: Builder) -> None:
    """Register a builder for a connector kind (mcp today; others later)."""
    _builders[kind] = builder


def known_kinds() -> set[str]:
    return set(_builders)


def build_connector(config: ConnectorConfig) -> Connector:
    try:
        builder = _builders[config.kind]
    except KeyError:
        raise UnknownConnectorKindError(config.kind) from None
    return builder(config)


def _build_mcp(config: ConnectorConfig) -> Connector:
    settings = McpConnectorSettings.model_validate(config.settings)
    return MCPClientConnector(name=config.name, settings=settings)


def _build_rest(config: ConnectorConfig) -> Connector:
    settings = RestConnectorSettings.model_validate(config.settings)
    return RestConnector(name=config.name, settings=settings)


def _build_webhook(config: ConnectorConfig) -> Connector:
    settings = RestConnectorSettings.model_validate(config.settings)
    return WebhookConnector(name=config.name, settings=settings, kind="webhook")


register_kind("mcp", _build_mcp)
register_kind("rest", _build_rest)
register_kind("webhook", _build_webhook)

"""MCP client connector that ingests tools and resources from an external server."""

from __future__ import annotations

import json
import os
import re
from collections.abc import Mapping
from typing import Any

from fastmcp import Client, FastMCP
from fastmcp.client.transports import StreamableHttpTransport

from agentic_odi_connectors.models import (
    HealthStatus,
    IngestBatch,
    IngestRecord,
    McpConnectorSettings,
)
from agentic_odi_connectors.protocol import Connector

_ENV_VAR_PATTERN = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}")


class MissingEnvironmentError(RuntimeError):
    """Raised when a connector needs credentials that are not in the environment."""

    def __init__(self, names: list[str]) -> None:
        self.names = names
        super().__init__("Missing environment variable(s): " + ", ".join(names))


def _expand_env(value: str, environ: Mapping[str, str]) -> str:
    return _ENV_VAR_PATTERN.sub(lambda match: environ.get(match.group(1), ""), value)


def _to_dict(obj: Any) -> dict[str, Any]:
    if hasattr(obj, "model_dump"):
        dumped = obj.model_dump(mode="json")
        if isinstance(dumped, dict):
            return dumped
    return {"repr": repr(obj)}


def _content_text(obj: Any) -> str:
    parts: list[str] = []
    content = getattr(obj, "content", None)
    if content is None:
        text = getattr(obj, "text", None)
        return text if isinstance(text, str) else json.dumps(_to_dict(obj))
    for item in content:
        text = getattr(item, "text", None)
        if isinstance(text, str):
            parts.append(text)
    return "\n".join(parts) if parts else json.dumps(_to_dict(obj))


class MCPClientConnector(Connector):
    """Pulls catalog, resources, and optional tool results from an MCP server."""

    kind = "mcp"

    def __init__(
        self,
        name: str,
        settings: McpConnectorSettings,
        *,
        server: FastMCP | None = None,
    ) -> None:
        self.name = name
        self.settings = settings
        self._server = server

    def transport(self) -> StreamableHttpTransport | FastMCP:
        """Build the MCP transport, resolving credentials from the environment."""
        if self._server is not None:
            return self._server
        missing = sorted(name for name in self.settings.env_vars if not os.environ.get(name))
        if missing:
            raise MissingEnvironmentError(missing)
        headers = {
            key: _expand_env(value, os.environ) for key, value in self.settings.headers.items()
        }
        return StreamableHttpTransport(
            url=_expand_env(self.settings.url, os.environ),
            headers=headers or None,
            auth="oauth" if self.settings.auth == "oauth" else None,
        )

    def _client(self) -> Client:
        return Client(self.transport())

    async def health(self) -> HealthStatus:
        try:
            async with self._client() as client:
                tools = await client.list_tools()
                resources = await client.list_resources()
            return HealthStatus(
                ok=True,
                message="reachable",
                details={
                    "tool_count": len(tools),
                    "resource_count": len(resources),
                },
            )
        except MissingEnvironmentError as exc:
            return HealthStatus(
                ok=False,
                message=str(exc),
                details={"missing_env": exc.names},
            )
        except Exception as exc:  # noqa: BLE001
            return HealthStatus(ok=False, message=str(exc))

    async def ingest(self) -> IngestBatch:
        batch = IngestBatch(connector_name=self.name)
        try:
            async with self._client() as client:
                tools = await client.list_tools()
                resources = await client.list_resources()
                tool_dicts = [_to_dict(tool) for tool in tools]
                resource_dicts = [_to_dict(resource) for resource in resources]
                catalog_raw = {"tools": tool_dicts, "resources": resource_dicts}
                batch.records.append(
                    IngestRecord(
                        source_name=self.name,
                        source_kind=self.kind,
                        item_type="catalog",
                        name="mcp-catalog",
                        content=json.dumps(catalog_raw, indent=2),
                        raw=catalog_raw,
                    )
                )
                for resource in resources:
                    uri = str(getattr(resource, "uri", ""))
                    name = str(getattr(resource, "name", None) or uri)
                    try:
                        contents = await client.read_resource(uri)
                        content_text = "\n".join(
                            getattr(item, "text", "") or "" for item in contents
                        )
                        batch.records.append(
                            IngestRecord(
                                source_name=self.name,
                                source_kind=self.kind,
                                item_type="resource",
                                name=name,
                                content=content_text,
                                raw={"uri": uri, "resource": _to_dict(resource)},
                            )
                        )
                    except Exception as exc:  # noqa: BLE001
                        batch.errors.append(f"Failed to read resource {uri}: {exc}")
                configured_tools = self.settings.tools
                available = {str(getattr(tool, "name", "")) for tool in tools}
                for tool_name in configured_tools:
                    if tool_name not in available:
                        batch.errors.append(f"Tool not found: {tool_name}")
                        continue
                    try:
                        result = await client.call_tool(tool_name, {})
                        batch.records.append(
                            IngestRecord(
                                source_name=self.name,
                                source_kind=self.kind,
                                item_type="tool_result",
                                name=tool_name,
                                content=_content_text(result),
                                raw={"tool": tool_name, "result": _to_dict(result)},
                            )
                        )
                    except Exception as exc:  # noqa: BLE001
                        batch.errors.append(f"Failed to call tool {tool_name}: {exc}")
        except Exception as exc:  # noqa: BLE001
            batch.errors.append(str(exc))
        return batch

"""REST and webhook connector kinds.

Both kinds share one HTTP puller: a REST endpoint returns a JSON document, and a
webhook connector posts a configured request (usually to a webhook inbox or a
subscription endpoint) and normalizes the JSON response. The transport is
injectable so tests never touch the network.
"""

from __future__ import annotations

import json
import urllib.request
from collections.abc import Callable
from typing import Any

from agentic_odi_connectors.models import (
    HealthStatus,
    IngestBatch,
    IngestRecord,
    RestConnectorSettings,
)
from agentic_odi_connectors.protocol import Connector

FetchResult = tuple[int, bytes]
Fetcher = Callable[[str, str, dict[str, str], bytes | None, float], FetchResult]


def _default_fetch(
    method: str,
    url: str,
    headers: dict[str, str],
    body: bytes | None,
    timeout: float,
) -> FetchResult:
    request = urllib.request.Request(url, data=body, headers=headers, method=method)
    with urllib.request.urlopen(request, timeout=timeout) as response:  # nosec B310
        return int(response.status), response.read()


def _lookup(payload: Any, path: str) -> Any:
    current = payload
    for part in path.split("."):
        if not isinstance(current, dict) or part not in current:
            return None
        current = current[part]
    return current


class RestConnector(Connector):
    """Pulls JSON records from an HTTP endpoint into the ingest sink."""

    kind = "rest"

    def __init__(
        self,
        name: str,
        settings: RestConnectorSettings,
        *,
        kind: str | None = None,
        fetcher: Fetcher | None = None,
    ) -> None:
        self.name = name
        self.settings = settings
        self.kind = kind or type(self).kind
        self._fetch = fetcher or _default_fetch

    def _request(self) -> FetchResult:
        body = None
        headers = dict(self.settings.headers)
        if self.settings.json_body is not None:
            body = json.dumps(self.settings.json_body).encode("utf-8")
            headers.setdefault("Content-Type", "application/json")
        return self._fetch(
            self.settings.method,
            self.settings.url,
            headers,
            body,
            self.settings.timeout,
        )

    def _items(self, payload: Any) -> list[Any]:
        if self.settings.records_key:
            extracted = _lookup(payload, self.settings.records_key)
            if isinstance(extracted, list):
                return extracted
        if isinstance(payload, list):
            return payload
        if isinstance(payload, dict):
            for key in ("records", "items", "data"):
                value = payload.get(key)
                if isinstance(value, list):
                    return value
        return [payload]

    def _record(self, item: Any, index: int) -> IngestRecord:
        if isinstance(item, dict):
            name = str(
                item.get("name")
                or item.get("title")
                or item.get("id")
                or f"{self.name}-{index + 1}"
            )
            content = None
            for key in ("content", "text", "description", "body", "summary"):
                if isinstance(item.get(key), str):
                    content = item[key]
                    break
            if content is None:
                content = json.dumps(item, indent=2, default=str)
            raw = item
        elif isinstance(item, str):
            name = f"{self.name}-{index + 1}"
            content = item
            raw = {"value": item}
        else:
            name = f"{self.name}-{index + 1}"
            content = json.dumps(item, default=str)
            raw = {"value": item}
        return IngestRecord(
            source_name=self.name,
            source_kind=self.kind,
            item_type=self.settings.item_type,
            name=name,
            content=content,
            raw=raw,
        )

    async def health(self) -> HealthStatus:
        try:
            status, _ = self._request()
        except Exception as exc:  # noqa: BLE001
            return HealthStatus(ok=False, message=str(exc))
        ok = 200 <= status < 400
        return HealthStatus(
            ok=ok,
            message="reachable" if ok else f"HTTP {status}",
            details={"status": status, "url": self.settings.url},
        )

    async def ingest(self) -> IngestBatch:
        batch = IngestBatch(connector_name=self.name)
        try:
            status, body = self._request()
        except Exception as exc:  # noqa: BLE001
            batch.errors.append(str(exc))
            return batch
        if not 200 <= status < 400:
            batch.errors.append(f"HTTP {status} from {self.settings.url}")
            return batch
        text = body.decode("utf-8", errors="replace")
        try:
            payload: Any = json.loads(text)
        except json.JSONDecodeError:
            payload = text
        records = self._items(payload)
        for index, item in enumerate(records):
            batch.records.append(self._record(item, index))
        return batch


class WebhookConnector(RestConnector):
    """Posts to a webhook endpoint and ingests the JSON response."""

    kind = "webhook"

"""Backend abstraction for the CLI.

Two backends implement the same :class:`Backend` seam:

* :class:`LocalBackend` runs the ODI logic directly against a local SQLite
  store (no server required).
* :class:`MCPBackend` delegates to a remote MCP server over HTTP, which may be
  a local ``python -m agentic_odi_mcp_server`` process or a hosted endpoint.

Commands resolve a backend once from the options stored on
:mod:`agentic_odi_cli.context`. Keeping the local and remote paths behind one interface
means the same command works against either, and a future hosted backend only
has to implement ``call``.
"""

from __future__ import annotations

import asyncio
import json
import os
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

import typer

if TYPE_CHECKING:
    from agentic_odi_core import ODIService

# Kept as literals so importing the CLI does not pull in the core package
# (``agentic-odi --version`` must stay lightweight). ``tests/contract`` asserts
# these keys match ``agentic_odi_core.contract.TOOL_NAMES``.

DEFAULT_BACKEND = "local"
DEFAULT_MCP_URL = "http://localhost:8000/mcp"
DEFAULT_MCP_TIMEOUT = 30.0

_VALUE_RANGE_ERROR = "importance and satisfaction must be between 1.0 and 10.0"

_CUSTOMER_VALUE_FIELDS = (
    "direction",
    "unit_of_measure",
    "object_of_control",
    "contextual_clarifier",
    "statement",
    "importance",
    "satisfaction",
    "value_metrics",
)

_BUSINESS_VALUE_FIELDS = {
    "category": "category",
    "business_statement": "statement",
    "detail": "detail",
    "estimated_annual_value": "estimated_annual_value",
    "confidence": "confidence",
}


class BackendError(Exception):
    """A user-facing failure: not found, invalid input, or unreachable server."""


def mcp_timeout() -> float:
    """Resolve the MCP call timeout in seconds (``AGENTIC_ODI_MCP_TIMEOUT``)."""
    raw = os.environ.get("AGENTIC_ODI_MCP_TIMEOUT")
    if not raw:
        return DEFAULT_MCP_TIMEOUT
    try:
        return float(raw)
    except ValueError:
        return DEFAULT_MCP_TIMEOUT


def _validation_message(exc: Exception) -> str:
    errors = getattr(exc, "errors", None)
    if callable(errors):
        try:
            first = errors()[0]
        except (IndexError, TypeError):
            return str(exc)
        return f"Invalid customer outcome: {first.get('msg', exc)}"
    return f"Invalid customer outcome: {exc}"


class Backend(ABC):
    @abstractmethod
    def call(self, tool_name: str, args: dict[str, Any]) -> Any:
        """Run ``tool_name`` and return parsed data (dict, list, str, or float)."""


class LocalBackend(Backend):
    """Run ODI logic in-process against a local SQLite store."""

    def __init__(self, db_path: str | None = None) -> None:
        self._db_path = db_path
        self._service: ODIService | None = None

    @property
    def service(self) -> ODIService:
        if self._service is None:
            from agentic_odi_core import ODIService
            from agentic_odi_core.sqlite_repository import SQLiteRepository

            self._service = ODIService(SQLiteRepository(db_path=self._db_path))
        return self._service

    def call(self, tool_name: str, args: dict[str, Any]) -> Any:
        handler = _LOCAL_HANDLERS.get(tool_name)
        if handler is None:
            raise NotImplementedError(f"Unknown tool: {tool_name}")
        return handler(self, args)

    def _add_job(self, args: dict[str, Any]) -> dict[str, Any]:
        job = self.service.add_job(name=args["name"], description=args.get("description"))
        return job.model_dump()

    def _get_jobs(self, args: dict[str, Any]) -> list[dict[str, Any]]:
        return [job.model_dump() for job in self.service.get_jobs()]

    def _get_job(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import job_not_found

        job_id = args["job_id"]
        job = self.service.get_job(job_id)
        if job is None:
            raise BackendError(job_not_found(job_id))
        return job.model_dump()

    def _update_job(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import JobNotFoundError, job_not_found

        updates: dict[str, Any] = {key: args[key] for key in ("name", "description") if key in args}
        try:
            job = self.service.update_job(args["job_id"], updates)
        except JobNotFoundError:
            raise BackendError(job_not_found(args["job_id"])) from None
        return job.model_dump()

    def _delete_job(self, args: dict[str, Any]) -> str:
        from agentic_odi_core import JobNotFoundError, job_not_found

        job_id = args["job_id"]
        try:
            self.service.delete_job(job_id)
        except JobNotFoundError:
            raise BackendError(job_not_found(job_id)) from None
        return job_id

    def _add_step(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import JobNotFoundError, job_not_found

        try:
            step = self.service.add_step(
                job_id=args["job_id"], name=args["name"], order=args["order"]
            )
        except JobNotFoundError:
            raise BackendError(job_not_found(args["job_id"])) from None
        return step.model_dump()

    def _get_job_map(self, args: dict[str, Any]) -> list[dict[str, Any]]:
        from agentic_odi_core import job_not_found

        job_id = args["job_id"]
        if self.service.get_job(job_id) is None:
            raise BackendError(job_not_found(job_id))
        return [step.model_dump() for step in self.service.get_job_map(job_id)]

    def _get_step(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import step_not_found

        step_id = args["step_id"]
        step = self.service.get_step(step_id)
        if step is None:
            raise BackendError(step_not_found(step_id))
        return step.model_dump()

    def _update_step(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import StepNotFoundError, step_not_found

        updates: dict[str, Any] = {key: args[key] for key in ("name", "order") if key in args}
        try:
            step = self.service.update_step(args["step_id"], updates)
        except StepNotFoundError:
            raise BackendError(step_not_found(args["step_id"])) from None
        return step.model_dump()

    def _delete_step(self, args: dict[str, Any]) -> str:
        from agentic_odi_core import StepNotFoundError, step_not_found

        step_id = args["step_id"]
        try:
            self.service.delete_step(step_id)
        except StepNotFoundError:
            raise BackendError(step_not_found(step_id)) from None
        return step_id

    def _add_outcome(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import (
            JobNotFoundError,
            StepNotFoundError,
            ValueOutOfRangeError,
            job_not_found,
            step_not_found,
        )

        step_id = args.get("step_id")
        try:
            outcome = self.service.add_outcome(
                job_id=args["job_id"],
                statement=args["statement"],
                importance=args.get("importance"),
                satisfaction=args.get("satisfaction"),
                step_id=step_id,
            )
        except JobNotFoundError:
            raise BackendError(job_not_found(args["job_id"])) from None
        except StepNotFoundError:
            raise BackendError(step_not_found(step_id)) from None
        except ValueOutOfRangeError as exc:
            raise BackendError(_VALUE_RANGE_ERROR) from exc
        return outcome.model_dump()

    def _get_outcomes(self, args: dict[str, Any]) -> list[dict[str, Any]]:
        from agentic_odi_core import job_not_found

        job_id = args["job_id"]
        if self.service.get_job(job_id) is None:
            raise BackendError(job_not_found(job_id))
        outcomes = self.service.get_outcomes(job_id=job_id, step_id=args.get("step_id"))
        return [outcome.model_dump() for outcome in outcomes]

    def _get_outcome(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import outcome_not_found

        outcome_id = args["outcome_id"]
        outcome = self.service.get_outcome(outcome_id)
        if outcome is None:
            raise BackendError(outcome_not_found(outcome_id))
        return outcome.model_dump()

    def _update_outcome(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import OutcomeNotFoundError, ValueOutOfRangeError, outcome_not_found

        updates: dict[str, Any] = {
            key: args[key]
            for key in ("statement", "importance", "satisfaction", "step_id")
            if key in args
        }
        try:
            outcome = self.service.update_outcome(args["outcome_id"], updates)
        except OutcomeNotFoundError:
            raise BackendError(outcome_not_found(args["outcome_id"])) from None
        except ValueOutOfRangeError as exc:
            raise BackendError(_VALUE_RANGE_ERROR) from exc
        return outcome.model_dump()

    def _delete_outcome(self, args: dict[str, Any]) -> str:
        from agentic_odi_core import OutcomeNotFoundError, outcome_not_found

        outcome_id = args["outcome_id"]
        try:
            self.service.delete_outcome(outcome_id)
        except OutcomeNotFoundError:
            raise BackendError(outcome_not_found(outcome_id)) from None
        return outcome_id

    def _add_customer_outcome(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import ValueOutOfRangeError
        from pydantic import ValidationError

        try:
            outcome = self.service.add_customer_outcome(
                job_id=args["job_id"],
                customer_value=args["customer_value"],
                business_value=args["business_value"],
                step_id=args.get("step_id"),
            )
        except ValidationError as exc:
            raise BackendError(_validation_message(exc)) from None
        except ValueOutOfRangeError as exc:
            raise BackendError(_VALUE_RANGE_ERROR) from exc
        return outcome.model_dump()

    def _get_customer_outcome(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import CustomerOutcomeNotFoundError, customer_outcome_not_found

        outcome_id = args["outcome_id"]
        try:
            outcome = self.service.get_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            raise BackendError(customer_outcome_not_found(outcome_id)) from None
        return outcome.model_dump()

    def _list_customer_outcomes(self, args: dict[str, Any]) -> list[dict[str, Any]]:
        outcomes = self.service.list_customer_outcomes(args.get("job_id"))
        return [outcome.model_dump() for outcome in outcomes]

    def _update_customer_outcome(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import (
            CustomerOutcome,
            CustomerOutcomeNotFoundError,
            customer_outcome_not_found,
        )
        from pydantic import ValidationError

        outcome_id = args["outcome_id"]
        try:
            existing = self.service.get_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            raise BackendError(customer_outcome_not_found(outcome_id)) from None

        customer_value = existing.customer_value.model_dump()
        for field in _CUSTOMER_VALUE_FIELDS:
            if field in args:
                customer_value[field] = args[field]
        business_value = existing.business_value.model_dump()
        for arg_key, field in _BUSINESS_VALUE_FIELDS.items():
            if arg_key in args:
                business_value[field] = args[arg_key]
        updates: dict[str, Any] = {
            "customer_value": customer_value,
            "business_value": business_value,
        }
        if "step_id" in args:
            updates["step_id"] = args["step_id"]

        candidate = existing.model_dump()
        candidate.update(updates)
        try:
            CustomerOutcome.model_validate(candidate)
        except ValidationError as exc:
            raise BackendError(_validation_message(exc)) from None

        outcome = self.service.update_customer_outcome(outcome_id, updates)
        return outcome.model_dump()

    def _delete_customer_outcome(self, args: dict[str, Any]) -> str:
        from agentic_odi_core import CustomerOutcomeNotFoundError, customer_outcome_not_found

        outcome_id = args["outcome_id"]
        try:
            self.service.delete_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            raise BackendError(customer_outcome_not_found(outcome_id)) from None
        return outcome_id

    def _add_evidence(self, args: dict[str, Any]) -> dict[str, Any]:
        from agentic_odi_core import (
            JobNotFoundError,
            OutcomeNotFoundError,
            StepNotFoundError,
            job_not_found,
            outcome_not_found,
            step_not_found,
        )

        try:
            evidence = self.service.add_evidence(
                source_name=args["source_name"],
