"""Feature flags management: defaults, persistence, querying, and environment overrides."""

from __future__ import annotations

import json
import os
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from agentic_odi_cli.profile import config_dir

FLAGS_FILE_NAME = "feature_flags.json"


@dataclass(frozen=True)
class FlagSpec:
    key: str
    description: str
    default: bool


DEFAULT_FLAGS: dict[str, FlagSpec] = {
    "experimental_connectors": FlagSpec(
        key="experimental_connectors",
        description="Enable experimental MCP connectors and ingest sources",
        default=False,
    ),
    "auto_update": FlagSpec(
        key="auto_update",
        description="Enable automatic CLI update checks on startup",
        default=True,
    ),
    "advanced_metrics": FlagSpec(
        key="advanced_metrics",
        description="Enable detailed latency & telemetry metrics in chat/CLI",
        default=False,
    ),
    "developer_mode": FlagSpec(
        key="developer_mode",
        description="Show developer debug information and raw MCP payload traces",
        default=False,
    ),
}


@dataclass
class FeatureFlags:
    """Store of feature flag states."""

    flags: dict[str, bool] = field(default_factory=dict)
    updated_at: str | None = None

    def get(self, key: str) -> bool:
        if key in self.flags:
            return self.flags[key]
        if key in DEFAULT_FLAGS:
            return DEFAULT_FLAGS[key].default
        return False

    def set(self, key: str, value: bool) -> None:
        self.flags[key] = value

    def reset(self, key: str | None = None) -> None:
        if key is None:
            self.flags.clear()
        elif key in self.flags:
            del self.flags[key]

    def to_dict(self) -> dict[str, Any]:
        full_flags = {}
        for k in DEFAULT_FLAGS:
            full_flags[k] = self.get(k)
        for k, v in self.flags.items():
            full_flags[k] = v
        return {
            "flags": full_flags,
            "updated_at": self.updated_at,
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> FeatureFlags:
        raw_flags = d.get("flags", {})
        flags = {k: bool(v) for k, v in raw_flags.items()}
        return cls(flags=flags, updated_at=d.get("updated_at"))


def flags_file() -> Path:
    return config_dir() / FLAGS_FILE_NAME


def load_flags() -> FeatureFlags:
    target = flags_file()
    if not target.exists():
        return FeatureFlags()
    try:
        with open(target, encoding="utf-8") as f:
            data = json.load(f)
        return FeatureFlags.from_dict(data)
    except Exception:  # noqa: BLE001
        return FeatureFlags()


def save_flags(flags: FeatureFlags) -> Path:
    cfg_dir = config_dir()
    cfg_dir.mkdir(parents=True, exist_ok=True)
    flags.updated_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    target = flags_file()
    tmp = target.with_name(target.name + ".tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(json.dumps(flags.to_dict(), indent=2))
    os.replace(tmp, target)
    return target


def is_enabled(key: str) -> bool:
    """Check if a feature flag is enabled with environment override support.

    Env var format: AGENTIC_ODI_FLAG_<KEY> (e.g. AGENTIC_ODI_FLAG_DEVELOPER_MODE=1)
    """
    env_var = f"AGENTIC_ODI_FLAG_{key.upper()}"
    if env_var in os.environ:
        val = os.environ[env_var].lower()
        return val in {"1", "true", "yes", "on"}
    return load_flags().get(key)

"""FastAPI app for the Living Studio sidecar."""

from __future__ import annotations

import os
from pathlib import Path

from agentic_odi_core import ODIService
from agentic_odi_core.repository import Repository
from agentic_odi_core.sqlite_repository import SQLiteRepository
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles

from agentic_odi_studio_api.studio.connectors import ConnectorService
from agentic_odi_studio_api.studio.router import router as studio_router

CORS_ORIGINS = [
    "tauri://localhost",
    "http://tauri.localhost",
    "http://localhost:5173",
    "http://127.0.0.1:5173",
    "http://localhost:8100",
    "http://127.0.0.1:8100",
]

DEFAULT_BACKEND = "local"


def default_spa_dist() -> Path:
    """Resolve the built SPA, preferring an explicit override."""
    configured = os.environ.get("AGENTIC_ODI_STUDIO_DIST")
    if configured:
        return Path(configured)
    return Path(__file__).resolve().parents[4] / "apps" / "studio" / "dist"


SPA_DIST = default_spa_dist()


def create_app(
    repo: Repository | None = None,
    backend: str | None = None,
    connectors: ConnectorService | None = None,
) -> FastAPI:
    if repo is None:
        repo = SQLiteRepository()
    service = ODIService(repo)
    app = FastAPI(title="Agentic ODI Studio API")
    app.state.service = service
    app.state.backend = backend or os.environ.get("AGENTIC_ODI_BACKEND") or DEFAULT_BACKEND
    app.state.connectors = connectors or ConnectorService()

    app.add_middleware(
        CORSMiddleware,
        allow_origins=CORS_ORIGINS,
        allow_credentials=False,
        allow_methods=["*"],
        allow_headers=["*"],
    )

    @app.get("/health")
    def health() -> dict:
        return {"status": "ok"}

    @app.get("/capabilities")
    def capabilities() -> dict:
        return {"capabilities": app.state.backend}

    app.include_router(studio_router)

    if SPA_DIST.is_dir() and not os.getenv("AGENTIC_ODI_DISABLE_SPA"):
        assets_dir = SPA_DIST / "assets"
        if assets_dir.is_dir():
            app.mount("/assets", StaticFiles(directory=assets_dir), name="assets")

        @app.get("/{full_path:path}", response_model=None)
        def spa_fallback(full_path: str) -> FileResponse | JSONResponse:
            candidate = (SPA_DIST / full_path).resolve()
            if full_path and candidate.is_file() and candidate.is_relative_to(SPA_DIST.resolve()):
                return FileResponse(candidate)
            index = SPA_DIST / "index.html"
            if index.is_file():
                return FileResponse(index)
            return JSONResponse({"detail": "Not Found"}, status_code=404)

    return app

"""Sidecar service that manages external connector registrations.

Wraps the shared ``connectors.json`` registry and the preset catalog so the
Living Studio can register, list, delete, and health-check connectors
without depending on an MCP server round-trip. The config path is shared
with the CLI via ``agentic_odi_connectors.paths.config_path``.
"""

from __future__ import annotations

import asyncio
from pathlib import Path
from typing import Any

from agentic_odi_connectors.catalog import (
    connector_config_from_preset,
    get_preset,
    list_presets,
)
from agentic_odi_connectors.factory import build_connector
from agentic_odi_connectors.models import ConnectorConfig, HealthStatus
from agentic_odi_connectors.paths import config_path
from agentic_odi_connectors.registry import ConnectorRegistry


class ConnectorService:
    """In-process management of the shared connector registry."""

    def __init__(self, path: Path | None = None, timeout: float = 15.0) -> None:
        self._path = path or config_path()
        self._timeout = timeout

    def _registry(self) -> ConnectorRegistry:
        return ConnectorRegistry(self._path)

    def catalog(self) -> list[dict[str, Any]]:
        """Return all known presets (recommended first) as plain dicts."""
        return [preset.model_dump() for preset in list_presets()]

    def add(
        self,
        name: str | None = None,
        preset_id: str | None = None,
        url: str | None = None,
    ) -> ConnectorConfig:
        """Register a connector from a preset or a custom URL."""
        if preset_id is not None:
            preset = get_preset(preset_id)
            config = connector_config_from_preset(preset, name=name, url=url)
        elif url is not None:
            if not name:
                raise ValueError("name is required when registering a custom URL")
            config = ConnectorConfig(name=name, kind="mcp", settings={"url": url})
        else:
            raise ValueError("must provide preset_id or url")
        self._registry().add(config)
        return config

    def list(self) -> list[ConnectorConfig]:
        return self._registry().list_all()

    def delete(self, name: str) -> bool:
        return self._registry().delete(name)

    def health(self, name: str) -> HealthStatus:
        """Run a connector's health check with a bounded timeout."""
        connector = build_connector(self._registry().get(name))
        try:
            return asyncio.run(asyncio.wait_for(connector.health(), timeout=self._timeout))
        except Exception as exc:  # noqa: BLE001
            return HealthStatus(ok=False, message=f"unhealthy: {exc}", details={})

    __all__ = ["ConnectorService"]

